golden.canonicalQuery:
run: duckdb.table('data/order_items.parquet') -> {
  aggregate: average_order_value is sale_price.sum() / nullif(count(order_id), 0)
}

run: duckdb.table('data/order_items.parquet') -> {
  group_by: user_id
  aggregate: lifetime_orders is count()
} -> {
  aggregate: top_customers is count() { where: lifetime_orders > 10 }
}

run: duckdb.table('data/order_items.parquet') extend {
  join_one: inventory_items is duckdb.table('data/inventory_items.parquet')
    on inventory_item_id = inventory_items.id
} -> {
  aggregate: products_sold is count(inventory_items.product_id)
}

run: duckdb.table('data/order_items.parquet') -> {
  group_by: user_id
  aggregate: first_order is min(created_at)
} -> {
  where: year(first_order) = 2022
  aggregate: new_customers is count()
}

run: duckdb.table('data/order_items.parquet') -> {
  aggregate:
    average_lifetime_value is
      sale_price.sum() { where: status != 'Cancelled' and status != 'Returned' }
      / nullif(count(user_id), 0)
}
